        private async Task<(bool ok,string? error)> Validate(Guid? id,CreateTrainingCatalogRequest r,CancellationToken ct){if(r.TrainingCategoryId==Guid.Empty)return(false,"Training category wajib dipilih.");if(!await _db.Set<MstTrainingCategory>().AnyAsync(x=>x.Id==r.TrainingCategoryId&&x.IsActive&&!x.IsDelete,ct))return(false,"Training category tidak ditemukan atau tidak aktif.");if(r.CertificationTypeId.HasValue&&!await _db.Set<MstCertificationType>().AnyAsync(x=>x.Id==r.CertificationTypeId&&x.IsActive&&!x.IsDelete,ct))return(false,"Certification type tidak ditemukan atau tidak aktif.");if(string.IsNullOrWhiteSpace(r.TrainingName))return(false,"Nama pelatihan wajib diisi.");if(!Types.Any(x=>x.Equals(r.TrainingType,StringComparison.OrdinalIgnoreCase)))return(false,"Training type tidak valid.");if(!Methods.Any(x=>x.Equals(r.DeliveryMethod,StringComparison.OrdinalIgnoreCase)))return(false,"Delivery method tidak valid.");if(r.DurationHours<0)return(false,"Durasi tidak boleh negatif.");if(r.ValidityMonths.HasValue&&r.ValidityMonths<=0)return(false,"Validity months harus lebih dari 0.");if(r.RequiresAssessment&&!r.MinimumPassingScore.HasValue)return(false,"Minimum passing score wajib ketika assessment diperlukan.");if(r.MinimumPassingScore is <0 or >100)return(false,"Minimum passing score harus antara 0 dan 100.");var name=r.TrainingName.Trim().ToLower();var q=_db.Set<MstTrainingCatalog>().AsNoTracking().Where(x=>!x.IsDelete&&x.TrainingCategoryId==r.TrainingCategoryId&&x.TrainingName.ToLower()==name);if(id.HasValue)q=q.Where(x=>x.Id!=id);if(await q.AnyAsync(ct))return(false,"Nama pelatihan pada kategori tersebut sudah digunakan.");return(true,null);}
