        private IQueryable<MstTrainingCatalog> Filter(IQueryable<MstTrainingCatalog> q,Guid? c,Guid? cert,string? type,string? method,bool? mandatory,bool? assess,bool? issue,bool? active,string? search){if(c.HasValue)q=q.Where(x=>x.TrainingCategoryId==c);if(cert.HasValue)q=q.Where(x=>x.CertificationTypeId==cert);if(!string.IsNullOrWhiteSpace(type))q=q.Where(x=>x.TrainingType==Canon(type,Types));if(!string.IsNullOrWhiteSpace(method))q=q.Where(x=>x.DeliveryMethod==Canon(method,Methods));if(mandatory.HasValue)q=q.Where(x=>x.IsMandatory==mandatory);if(assess.HasValue)q=q.Where(x=>x.RequiresAssessment==assess);if(issue.HasValue)q=q.Where(x=>x.IssuesCertificate==issue);if(active.HasValue)q=q.Where(x=>x.IsActive==active);if(!string.IsNullOrWhiteSpace(search)){var k=search.Trim().ToLower();q=q.Where(x=>x.TrainingCode.ToLower().Contains(k)||x.TrainingName.ToLower().Contains(k)||(x.DefaultProviderName!=null&&x.DefaultProviderName.ToLower().Contains(k))||(x.TrainingCategory!=null&&x.TrainingCategory.TrainingCategoryName.ToLower().Contains(k)));}return q;}
        private static IOrderedQueryable<MstTrainingCatalog> Sort(IQueryable<MstTrainingCatalog>q,string? b,string? d){var desc=string.Equals(d,"desc",StringComparison.OrdinalIgnoreCase);return(b??"trainingName").ToLowerInvariant() switch{"createdatetime"=>desc?q.OrderByDescending(x=>x.CreateDateTime):q.OrderBy(x=>x.CreateDateTime),"trainingcode"=>desc?q.OrderByDescending(x=>x.TrainingCode):q.OrderBy(x=>x.TrainingCode),"categoryname"=>desc?q.OrderByDescending(x=>x.TrainingCategory!.TrainingCategoryName):q.OrderBy(x=>x.TrainingCategory!.TrainingCategoryName),"durationhours"=>desc?q.OrderByDescending(x=>x.DurationHours):q.OrderBy(x=>x.DurationHours),"isactive"=>desc?q.OrderByDescending(x=>x.IsActive):q.OrderBy(x=>x.IsActive),_=>desc?q.OrderByDescending(x=>x.TrainingName):q.OrderBy(x=>x.TrainingName)};}
        private async Task<string> Code(CancellationToken ct){var l=await _db.Set<MstTrainingCatalog>().Where(x=>!x.IsDelete&&x.TrainingCode.StartsWith(Prefix)).Select(x=>x.TrainingCode).ToListAsync(ct);var u=l.Select(x=>x.Replace(Prefix,"")).Where(x=>int.TryParse(x,out _)).Select(int.Parse).ToHashSet();var n=1;while(u.Contains(n))n++;return Prefix+n.ToString("D5");}
        private void SoftDelete(MstTrainingCatalog e){var n=DateTime.UtcNow;var a=Uid();e.IsDelete=true;e.IsActive=false;e.DeleteDateTime=n;e.DeleteBy=a;e.UpdateDateTime=n;e.UpdateBy=a;} private Guid Uid(){var s=User.FindFirstValue(ClaimTypes.NameIdentifier)??User.FindFirstValue("user_id");return Guid.TryParse(s,out var id)?id:Guid.Empty;} private static string? Text(string? s)=>string.IsNullOrWhiteSpace(s)?null:s.Trim();private static Guid? GuidVal(Guid? g)=>g is null||g==Guid.Empty?null:g;private static string Canon(string v,IEnumerable<string> a)=>a.First(x=>x.Equals(v.Trim(),StringComparison.OrdinalIgnoreCase));
        private async Task<Dictionary<Guid,string>> Actors(IEnumerable<Guid> ids,CancellationToken ct){var v=ids.Where(x=>x!=Guid.Empty).Distinct().ToList();return await _db.Users.Where(x=>v.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,x=>x.DisplayName??x.UserName??x.Email??x.UserCode,ct);}private static string? Actor(IReadOnlyDictionary<Guid,string>a,Guid id)=>id==Guid.Empty?null:a.GetValueOrDefault(id);private static void NormPage(ref int p,ref int s){p=Math.Max(p,1);s=s<1?25:Math.Min(s,100);}private static List<TrainingCatalogStringOptionResponse> Periods()=>new(){new(){Value="today",Label="Hari ini"},new(){Value="last7days",Label="7 hari terakhir"},new(){Value="thismonth",Label="Bulan ini"},new(){Value="lastmonth",Label="Bulan lalu"}};
        private static IQueryable<MstTrainingCatalog>Date(IQueryable<MstTrainingCatalog>q,DateTime?s,DateTime?e,string?p){var r=Range(s,e,p);if(r.Item1.HasValue)q=q.Where(x=>x.CreateDateTime>=r.Item1.Value);if(r.Item2.HasValue)q=q.Where(x=>x.CreateDateTime<r.Item2.Value);return q;}private static(DateTime?,DateTime?)Range(DateTime?s,DateTime?e,string?p){if(s.HasValue||e.HasValue)return(s?.Date,e?.Date.AddDays(1));var t=DateTime.UtcNow.Date;return p?.ToLowerInvariant()switch{"today"=>(t,t.AddDays(1)),"last7days"=>(t.AddDays(-6),t.AddDays(1)),"thismonth"=>(new DateTime(t.Year,t.Month,1),new DateTime(t.Year,t.Month,1).AddMonths(1)),"lastmonth"=>(new DateTime(t.Year,t.Month,1).AddMonths(-1),new DateTime(t.Year,t.Month,1)),_=>(null,null)};}
